    @Test
    @DisplayName("an empty board has no winner")
    public void anEmptyBoardHasNoWinner() {

        //GIVEN
        var board = new String[]{
            ". . . . .",
            " . . . . .",
            "  . . . . .",
            "   . . . . .",
            "    . . . . ."
        };
        Connect cut = new Connect(board);

        //WHEN
        var winner = cut.computeWinner();

        //THEN
        assertThat(winner).isEqualTo(Winner.NONE);
    }

